import { Workflow } from '@systemfsoftware/effect-cell-types'
import * as Result from 'effect/Result'
import * as S from 'effect/Schema'

const ProbeDecisionTypeId: unique symbol = Symbol.for('probe/ProbeDecision')
type ProbeDecisionTypeId = typeof ProbeDecisionTypeId

export class ProbeAccepted extends S.TaggedClass<ProbeAccepted>()('ProbeAccepted', {
  value: S.Int,
}) {
  readonly [ProbeDecisionTypeId] = ProbeDecisionTypeId
}

export class ProbeRejected extends S.TaggedClass<ProbeRejected>()('ProbeRejected', {
  value: S.Int,
}) {
  readonly [ProbeDecisionTypeId] = ProbeDecisionTypeId
}

export class ProbeCommand extends S.TaggedClass<ProbeCommand>()('ProbeCommand', {
  value: S.Int,
}) {}

export class ProbeRefused extends S.TaggedError<ProbeRefused>()('ProbeRefused', {
  value: S.Int,
}) {}

export const probeDecision = Workflow.make(
  ProbeCommand,
  (command): Result.Result<ProbeAccepted | ProbeRejected, ProbeRefused> => {
    if (command.value > 0) {
      return Result.succeed(ProbeAccepted.make({ value: command.value }))
    }
    return Result.succeed(ProbeRejected.make({ value: command.value }))
  },
)
